{
  "window_id": "w0027",
  "observed_failures": [
    {
      "filename": "034.jpg",
      "field": "date",
      "predicted": "2018-08-09",
      "failure_mode": "date digit swap / wrong month-day",
      "evidence": "Receipt (Perniagaan Zheng Hui) shows a single clearly printed date 'Date: 09/03/2018' in DD/MM/YYYY form. Predicted ISO date transposes to month=08, day=09, which cannot be produced by any pattern in DATE_PATTERNS from that string. Indicates OCR mis-read of the slash-separated date or a second date-like token elsewhere on the receipt was matched first.",
      "amount_correct": true
    },
    {
      "filename": "074.jpg",
      "field": "total_amount",
      "predicted": "702.00",
      "failure_mode": "wrong number picked for Grand Total",
      "evidence": "Receipt (Thai Delicious Restaurant) clearly shows 'Total : 92.80' and 'Grand Total : 92.80' with 'Cash Received : 100.00' and 'Change : 7.20' and 'AVERAGE / PAX(S) : 23.20'. '702.00' does not appear anywhere on the printed receipt. This is consistent with (a) OCR mis-reading '92.80' as something like '702' or (b) selecting a non-total line (e.g., concatenating qty/price columns like '7 2.50 2.50' into '702.00') because the extractor only trusted one OCR pass instead of voting across variants, and did not restrict the total-number regex to a `d+\\.dd` form on the matched line."
    },
    {
      "filename": "077.jpg",
      "field": "total_amount",
      "predicted": "23.26",
      "failure_mode": "picked pre-rounding Total rather than final TOTAL line",
      "evidence": "Receipt (Banh Mi CafE) shows 'Total (Inclusive of GST): 23.26', 'Rounding Adj: -0.01', then 'TOTAL: 23.25'. The task's priority list puts bare 'TOTAL' in the lowest tier, so the extractor matched the earlier 'Total (Inclusive of GST)' line in a higher tier and short-circuited. The final 'TOTAL: 23.25' line is the intended grand total after rounding adjustment."
    },
    {
      "filename": "078.jpg",
      "field": "total_amount",
      "predicted": "",
      "failure_mode": "empty string written instead of null for failed extraction",
      "evidence": "Receipt (Daiso/AEON) prints 'Sub-total 5.90', 'Total Sales Incl GST 5.90', 'Total After Adj Incl GST 5.90', 'CASH 10.00'. A correct extractor should return '5.90'. Instead the delivered Excel cell contains the empty string '' (not a real null). Two defects: (1) the extractor failed on a readable 'Total Sales Incl GST' / 'Total After Adj Incl GST' line because neither keyword is in the priority list; (2) when extraction fails, the pipeline writes '' instead of None, violating the task's 'value is set to null' contract."
    }
  ],
  "root_causes": [
    {
      "id": "RC1_total_priority_misses_final_TOTAL",
      "summary": "Priority-tier total extraction picks the first keyword match and does not re-evaluate later, more authoritative 'TOTAL' lines that appear after rounding/adjustment rows.",
      "affects": ["077.jpg"],
      "detail": "When a receipt has 'Total (Inclusive of GST): X' followed by 'Rounding Adj' and then a final standalone 'TOTAL: Y', the current tier design treats the earlier 'Total ...' as a Tier-3/4 match and short-circuits. Final 'TOTAL' after rounding is the canonical grand total but is only considered at the same tier."
    },
    {
      "id": "RC2_missing_keywords_for_total_sales_incl_gst",
      "summary": "Keyword list for totals does not cover common Malaysian POS variants.",
      "affects": ["078.jpg"],
      "detail": "Variants like 'Total Sales Incl GST', 'Total After Adj Incl GST', 'Total RM Incl. of GST', 'Rounded Total', 'Total Inclusive of GST', 'Takeout Total', 'Total Rounded', 'Net Total' are not all reliably matched by the current priority tiers, causing total extraction to fall through to None (or to garbage via fallback)."
    },
    {
      "id": "RC3_single_pass_ocr_with_no_variant_voting",
      "summary": "Total/date extraction trusts a single OCR pass per image and has no variant-level agreement/voting, so a single mis-read on a small, fragile numeric line propagates directly to output.",
      "affects": ["074.jpg", "034.jpg"],
      "detail": "The original image-ocr skill documents multi-pass OCR but does not require the receipt extractor to vote across preprocessing/PSM variants and take the majority candidate. Impossible outputs like '702.00' for a '92.80' receipt would be rejected by majority agreement across variants."
    },
    {
      "id": "RC4_null_vs_empty_string_on_failure",
      "summary": "On extraction failure the pipeline wrote '' into the Excel cell, but the task contract requires a real null (empty cell).",
      "affects": ["078.jpg"],
      "detail": "The downstream xlsx writer did not coerce missing extractions to None and did not force the column dtype to object. Any str('') or NaN that leaks through becomes a non-null cell that the line-by-line grader compares as a mismatch."
    },
    {
      "id": "RC5_date_candidate_selection_order",
      "summary": "Date extraction takes the first regex hit in reading order without sanity-checking against other dates on the receipt or against the DD/MM/YYYY vs MM/DD/YYYY disambiguation.",
      "affects": ["034.jpg"],
      "detail": "A single mis-OCRed digit can turn '09/03/2018' into a string that still parses as a valid DD/MM/YYYY date but with swapped fields, or a secondary date-like token (GST id, invoice number with slashes, time-stamped 'Print Date' etc.) is matched instead of the primary 'Date:' line."
    },
    {
      "id": "RC6_no_sanity_check_on_amount_shape",
      "summary": "Extracted totals are not validated against a plausible receipt-amount shape (≤~6 digits before the decimal, exactly two decimals, within a sane magnitude for the item list).",
      "affects": ["074.jpg"],
      "detail": "A result like '702.00' from a receipt whose items sum to under 100 should be flagged and demoted in favor of an alternate candidate. The current code accepts any regex-matching number on the keyword line."
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defects": [
        "Priority tiers for receipt totals do not include 'TOTAL SALES INCL GST', 'TOTAL AFTER ADJ INCL GST', 'TOTAL RM INCL(. OF) GST', 'ROUNDED TOTAL', 'TOTAL INCLUSIVE OF GST', 'TOTAL ROUNDED', 'TAKEOUT TOTAL'.",
        "Tier evaluation short-circuits on the first match in reading order; it does not prefer the last qualifying match when several totals of the same tier appear (needed to pick the post-rounding 'TOTAL' line).",
        "No rule to prefer a later 'TOTAL' line over an earlier 'Total (Inclusive of GST)' when a 'Rounding Adj' line appears between them.",
        "No requirement that the chosen number be a strict d+\\.dd (or d{1,3}(,d{3})*\\.dd) token, with currency prefixes/suffixes stripped — permits ingesting concatenated digits from adjacent columns.",
        "Multi-pass OCR is described but the receipt-field extractor is not required to run multiple preprocess/PSM variants and vote on the total/date candidates.",
        "Date extraction returns the first regex hit instead of preferring the token on a line containing 'DATE', 'INVOICE DATE', or 'PRINT DATE', then falling back to earliest valid match.",
        "No per-image try/except guarantee: a crash on one image can skip a row rather than emitting a row with (None, None)."
      ]
    },
    {
      "skill": "xlsx",
      "defects": [
        "Strict-schema section does not state explicitly that failed extractions must be written as Python None (not '' and not 'NaN'), and does not show a defensive coercion step before to_excel.",
        "Does not require re-reading the produced file and asserting that (a) empty extractions appear as real nulls, (b) total_amount values match ^\\d+\\.\\d{2}$, (c) date values match ^\\d{4}-\\d{2}-\\d{2}$ or are null, before finishing.",
        "Does not warn that pandas will silently coerce a mixed None/str column to object only if dtype is forced; otherwise NaN leaks in and is rendered as a non-null string by some readers."
      ]
    },
    {
      "skill": "openai-vision",
      "defects": [
        "No guidance for using vision OCR as a tie-breaker for Tesseract on receipts where the chosen total has low cross-variant agreement or fails sanity checks. The skill could be lightly extended to describe a 'confirm-the-total' prompt that returns a single JSON {date, total_amount} and is used only when Tesseract candidates disagree."
      ]
    },
    {
      "skill": "pdf",
      "defects": [
        "No defects relevant to this task; not used."
      ]
    },
    {
      "skill": "video-frame-extraction",
      "defects": [
        "No defects relevant to this task; not used."
      ]
    }
  ],
  "repair_recommendations": [
    {
      "skill": "image-ocr",
      "changes": [
        "Expand the keyword priority tiers to explicitly cover (case-insensitive, whitespace-tolerant): Tier A 'GRAND TOTAL'; Tier B 'TOTAL\\s*:?\\s*RM', 'TOTAL RM'; Tier C 'TOTAL AMOUNT'; Tier D 'ROUNDED TOTAL', 'TOTAL ROUNDED', 'TOTAL AFTER ADJ INCL GST', 'TOTAL SALES INCL GST', 'TOTAL RM INCL(. OF) GST', 'TOTAL INCLUSIVE OF GST', 'NETT? TOTAL', 'NET TOTAL', 'TAKEOUT TOTAL', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', '\\bTOTAL\\b', '\\bAMOUNT\\b'. Keep the existing exclusion keywords.",
        "Change tier evaluation so that within the matched tier the extractor picks the LAST non-excluded occurrence in reading order (not the first). Rationale: receipts typically print intermediate totals first and the final grand total last, especially after 'Rounding Adj'.",
        "Add a rule: if a 'ROUNDING ADJ' / 'ROUNDING ADJUSTMENT' line is detected, only totals that appear after that line are eligible for selection; if none, fall back to the earlier candidate.",
        "Tighten the number regex used on the chosen line to r'(?<![A-Z0-9])(\\d{1,3}(?:,\\d{3})*|\\d+)\\.(\\d{2})(?![A-Z0-9])' and reject any candidate that does not have exactly two decimals; strip 'RM'/'MYR'/'$' prefixes, strip commas, then format with f\"{v:.2f}\".",
        "Require multi-pass OCR for receipt total/date extraction: run at least {grayscale+autocontrast, inverted, sharpened, 2x upscaled} × {--psm 6, --psm 4, --psm 11}, extract a (total, date) candidate from each, and output the majority-voted candidate; break ties by preferring the candidate from --psm 6 on the autocontrast variant.",
        "Add a sanity check: discard total candidates whose magnitude is >10x the median of all other candidates found on the same image (catches '702.00' vs '92.80').",
        "Date extraction: scan line-by-line, prefer the match on a line whose uppercased text contains 'DATE' (but not 'PRINT DATE' if a non-print 'Date' line also exists, and not 'EXP' / 'EXPIRY'); only fall back to the first valid date anywhere. Keep DD/MM/YYYY as the first pattern tried, and when both DD/MM/YYYY and MM/DD/YYYY parses are valid, prefer DD/MM/YYYY (Malaysian receipt convention consistent with this corpus).",
        "Explicitly document the per-image contract: process_receipt(path) must return {'date': str|None, 'total_amount': str|None}, must never raise, and on any internal exception must return {'date': None, 'total_amount': None} so the batch still produces a row.",
        "Document that the returned total_amount is a string formatted f\"{v:.2f}\" and must never be a float, '', 'None', or 'NaN'."
      ]
    },
    {
      "skill": "xlsx",
      "changes": [
        "In the Strict-Schema section, add a bullet that failed extractions must be written as Python None (which becomes a real empty cell), and show the three-step pattern: build list of dicts with None for failures → DataFrame → df[col] = df[col].astype('object') for every string-typed column, then to_excel(..., index=False, sheet_name=exact_name).",
        "Add a re-read verification snippet that asserts, for the output of this family of tasks: the single sheet name matches exactly; columns match exactly; rows are sorted lexicographically by filename; every non-null total_amount matches ^\\d+\\.\\d{2}$; every non-null date matches ^\\d{4}-\\d{2}-\\d{2}$; empty extractions are real nulls (pd.isna is True) and are not the strings '', 'None', 'NaN', 'nan'.",
        "Call out that pandas will silently coerce a numeric-looking string column to float unless dtype 'object' is enforced, which would turn '47.70' into 47.7 and break grading."
      ]
    },
    {
      "skill": "openai-vision",
      "changes": [
        "Add a short 'receipt field confirmation' recipe: given an image and a list of Tesseract candidate (total, date) tuples, call gpt-4o with detail=high and the prompt 'Return ONLY JSON {\"date\":\"YYYY-MM-DD or null\",\"total_amount\":\"N.NN or null\"} for the grand total actually paid on this receipt'. Describe it as a tie-breaker only (invoked when majority voting across Tesseract variants is inconclusive or the top candidate fails the sanity check), not as the default path."
      ]
    },
    {
      "skill": "pdf",
      "changes": [
        "No changes required."
      ]
    },
    {
      "skill": "video-frame-extraction",
      "changes": [
        "No changes required."
      ]
    }
  ],
  "confidence": {
    "overall": 0.78,
    "notes": "High confidence that RC1 (prefer last TOTAL after rounding), RC2 (missing keyword variants), and RC4 (null vs empty string) are exact root causes for 077 and 078, respectively, because the receipt text is unambiguously visible and matches the predictions' failure shape. Medium-high confidence on RC3 for 074 (702.00 is clearly impossible on a 92.80 Thai-restaurant receipt and is best explained by a single-pass OCR mis-read of the Grand Total line or confusion with the quantity column; majority voting across variants would catch it). Medium confidence on RC5 for 034 because the exact OCR string is not in evidence, but the predicted 2018-08-09 cannot come from a correct read of '09/03/2018' under the documented patterns, so either the primary date line was mis-OCRed or a secondary date-like token was picked. The recommended fixes generalize to any receipt corpus and do not depend on oracle values for these 22 images."
  }
}
